void sense_rs_can_skd_init( void )
{
    set_skd_present(TRUE);	
}

//--------------------------------------------------------------------------//

Boolean sense_rs_skd_can( Boolean instant_level )
{			
	Boolean last_level = get_skd_present();

	set_skd_present( instant_level ); 

	if( last_level != instant_level )
	{			
		cmd_q_insert( get_skd_present() ? INPUT_SKD_SET : INPUT_SKD_CLR , SENSE_RS_CAN_TIMEOUT_CMD_Q);
                
        TRACE_SENSE_RS_CAN("\n\r[SK %s PRESENT]\n\r" , get_skd_present() ? "":"NOT" );					
	}              
	
    return get_skd_present();
}

